import './SortAllTasks.css'
import Dropdown from 'react-bootstrap/Dropdown';
import { PiSortAscending } from "react-icons/pi";


function SortAllTask(props){
    return(
        <div className="ContainerSortAllTasks">
             <Dropdown className={props.isFavorite?'dropdown favoriteSort':'dropdown'}>
      <Dropdown.Toggle  id="dropdown-basic">
<span><PiSortAscending size={25}/></span>  
<span>  sort by</span>  
<span style={{fontWeight:'bold'}}>{props.sortTitle}</span>
      </Dropdown.Toggle>

      <Dropdown.Menu>
        <Dropdown.Item onClick={()=>props.sortHandler('Due date')} >Due date</Dropdown.Item>
        <Dropdown.Item onClick={()=>props.sortHandler('Task name')} >Task name</Dropdown.Item>
      </Dropdown.Menu>
    </Dropdown>

        </div>
    )
}


export default SortAllTask